import ast
import re
from bisect import bisect_right
from html.parser import HTMLParser
from pathlib import PurePosixPath

from ast_grep_py import SgRoot
from pygments.lexers.configs import TOMLLexer
from pygments.lexers.data import JsonLexer
from pygments.lexers.shell import PowerShellLexer
from pygments.lexers.sql import PostgresLexer
from pygments.token import Comment

from docker_syntax import ensure_dockerfile_language


LANGUAGES = {
    "javascript": (".js", ".cjs", ".mjs", ".jsx"),
    "typescript": (".ts", ".cts", ".mts"),
    "tsx": (".tsx",),
    "python": (".py", ".pyi", ".pyw"),
    "bash": (".sh", ".bash"),
    "css": (".css",),
    "html": (".htm", ".html"),
    "swift": (".swift",),
    "ruby": (".rb",),
    "go": (".go",),
    "rust": (".rs",),
    "kotlin": (".kt", ".kts"),
    "yaml": (".yaml", ".yml"),
    "postgresql": (".sql",),
    "powershell": (".ps1", ".psm1", ".psd1"),
    "toml": (".toml",),
    "jsonc": (".jsonc",),
}
EXTENSIONS = {ext: language for language, extensions in LANGUAGES.items() for ext in extensions}
FILENAMES = {
    "Brewfile": "ruby",
    ".bashrc": "bash",
    ".bash_profile": "bash",
    ".bash_login": "bash",
    ".bash_logout": "bash",
    "biome.json": "jsonc",
    "deno.json": "jsonc",
}
DOCKER_SETTING = r"(?:skip=(?:all|[A-Z]\w*(?:,[A-Z]\w*)*)|error=(?:true|false))"
DOCKER_DIRECTIVE = re.compile(
    rf"[ \t]*#[ \t]*(?:(?i:syntax)\s*=\s*[^\s=]+|(?i:escape)\s*=\s*[\\`]"
    rf"|(?i:check)\s*=\s*{DOCKER_SETTING}(?:;{DOCKER_SETTING})*)[ \t]*"
)
JSON_CONFIG = re.compile(r"(?:tsconfig|jsconfig)(?:\.[^/]+)?\.json")
LEXERS = {"postgresql": PostgresLexer, "powershell": PowerShellLexer, "toml": TOMLLexer, "jsonc": JsonLexer}
EXCLUDED_DIRECTORIES = {
    ".git", ".next", ".venv", "__pycache__", "coverage", "dist",
    "generated", "node_modules", "third-party", "third_party", "vendor", "vendored",
}
GENERATED_NAMES = re.compile(r"(?:\.min|\.generated|\.gen|\.pb|_pb2(?:_grpc)?)\.[^.]+$")

COMMENT_KINDS = {
    "swift": ("comment", "multiline_comment"),
    "kotlin": ("line_comment", "multiline_comment"),
    "rust": ("line_comment", "block_comment"),
}
JAVASCRIPT = {"javascript", "typescript", "tsx"}

LICENSE = re.compile(
    r"^(?:SPDX-(?:License-Identifier|FileCopyrightText):\s*\S"
    r"|(?:Copyright(?:\s+\([cC]\))?|©)\s+(?:©\s*)?\d{4}\b"
    r"|@(?:license|preserve)\b"
    r"|Licensed under (?:the )?(?:Apache|MIT|BSD|GNU|Mozilla|ISC|Eclipse)\b"
    r"|Permission is hereby granted, free of charge\b)", re.I
)
DOC_TAG = re.compile(
    r"(?m)^\s*(?:\*\s*)?@(?:param|returns?|throws|typedef|type|template|property|callback"
    r"|overload|satisfies|implements|extends|link|example|deprecated|module|packageDocumentation|remarks|public)\b"
)
RULE_NAMES = r"[\w@./:-]+(?:\s*,\s*[\w@./:-]+)*"
JS_LINTER = rf"(?:eslint|oxlint)-(?:enable|disable(?:-next-line|-line)?)(?:\s+{RULE_NAMES})?(?:\s+--\s+.+)?"
STYLELINT = rf"stylelint-(?:enable|disable(?:-next-line|-line)?)(?:\s+{RULE_NAMES})?(?:\s+--\s+.+)?"
JS_DIRECTIVES = re.compile(
    rf"(?:{JS_LINTER}|biome-ignore\s+(?:lint|assist)/[\w-]+(?:/[\w-]+)*:\s*\S[^\n]*|@ts-(?:no)?check|@ts-(?:ignore|expect-error)(?:[:\s].*)?"
    r"|[#@]__PURE__|[#@]__NO_SIDE_EFFECTS__|[#@]\s*source(?:Mapping)?URL=\S+"
    r"|(?:istanbul|c8|v8) ignore (?:next(?: \d+)?|if|else|file|start|stop|end)"
    r"|prettier-ignore|@jsx(?:ImportSource|Runtime|Frag)?\s+\S+"
    r"|/\s*<reference\s+(?:path|types|lib|no-default-lib)=[^>]+/\s*>)"
)
PY_DIRECTIVES = re.compile(
    r"(?:noqa(?:\s*:\s*[\w]+(?:[\s,]+[\w]+)*)?|(?:ruff|flake8):\s*noqa(?:\s*:\s*[\w, ]+)?"
    r"|type:\s*ignore(?:\[[\w, -]+\])?|(?:pyright|mypy|pylint):\s*[\w-]+[=:][\w, .-]+"
    r"|fmt:\s*(?:on|off|skip)|pragma:\s*(?:no cover|no branch)|nosec(?:\s+[B\d, ]+)?)"
)
ENCODING = re.compile(r"(?:-\*-\s*)?coding[:=]\s*[-\w.]+(?:\s*-\*-)?")
GENERATED_HEADER = re.compile(r"^\s*(?://|#|/\*)\s*Code generated by .+ DO NOT EDIT\.(?:\s*\*/)?\s*$", re.M)


def path_language(path: str):
    file = PurePosixPath(path)
    if EXCLUDED_DIRECTORIES.intersection(file.parts[:-1]) or GENERATED_NAMES.search(file.name):
        return None
    if (file.name == "Dockerfile" or file.name.startswith("Dockerfile.") or file.suffix.lower() == ".dockerfile"):
        return None if file.suffix.lower() == ".dockerignore" else "dockerfile"
    if file.name in FILENAMES:
        return FILENAMES[file.name]
    if JSON_CONFIG.fullmatch(file.name):
        return "jsonc"
    if not file.suffix and not file.name.startswith("."):
        return "shebang"
    return EXTENSIONS.get(file.suffix.lower())


def executable_code_path(path: str) -> bool:
    return path_language(path) is not None


def shebang_language(first_line: str):
    if not first_line.startswith("#!"):
        return None
    words = first_line[2:].split()
    if not words or not words[0].startswith("/"):
        return None
    interpreter = PurePosixPath(words[0]).name
    if interpreter == "env":
        args = words[1:]
        if args[:1] == ["-S"]:
            args = args[1:]
        if not args:
            return None
        interpreter = PurePosixPath(args[0]).name
    if re.fullmatch(r"python(?:\d+(?:\.\d+)*)?", interpreter):
        return "python"
    if interpreter in {"sh", "bash", "dash"}:
        return "bash"
    return None


class _HtmlComments(HTMLParser):
    CDATA_CONTENT_ELEMENTS = ("script", "style", "textarea", "title")

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.language = None
        self.comments = []

    def handle_comment(self, data):
        self.comments.append(("html", self.getpos()[0], "<!--" + data + "-->"))

    def handle_starttag(self, tag, attrs):
        media_type = (dict(attrs).get("type") or "").lower().strip()
        if tag == "style" and media_type in ("", "text/css"):
            self.language = "css"
        elif tag == "script" and media_type in ("", "module", "text/javascript", "application/javascript", "text/ecmascript"):
            self.language = "javascript"

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self.language = None

    def handle_data(self, data):
        if self.language:
            offset = self.getpos()[0] - 1
            for language, line, text in _syntax_comments(self.language, data):
                self.comments.append((language, line + offset, text))


ACTION_REPOSITORY = r"[\w.-]+/[\w.-]+"
ACTION_VERSION_NOTE = re.compile(
    rf"#\s*(?:pin @|@|tag=|https://github\.com/(?P<repo>{ACTION_REPOSITORY})/releases/tag/)?"
    r"v?\d+(?:\.\d+){0,3}(?:[-+][\w.-]+)?\s*"
)
PINNED_ACTION = re.compile(rf"(?P<repo>{ACTION_REPOSITORY})(?:/[\w./-]+)?@[0-9a-fA-F]{{40}}")


def _workflow_version_note(comment):
    note = ACTION_VERSION_NOTE.fullmatch(comment.text())
    if not note:
        return False
    pair = comment.prev()
    if not pair or pair.kind() != "block_mapping_pair" or pair.range().end.line != comment.range().start.line:
        return False
    key, value = pair.field("key"), pair.field("value")
    if not key or key.text().strip("\"'") != "uses" or not value:
        return False
    action = PINNED_ACTION.fullmatch(value.text().strip("\"'"))
    if not action or (note["repo"] and note["repo"].casefold() != action["repo"].casefold()):
        return False
    keys = [node.field("key") for node in comment.ancestors() if node.kind() == "block_mapping_pair"]
    path = [key.text().strip("\"'") if key else None for key in reversed(keys)]
    return (len(path) == 2 and path[0] == "jobs"
            or len(path) == 3 and path[0] == "jobs" and path[2] == "steps")


def _syntax_comments(language, source, *, workflow=False):
    if language == "html":
        parser = _HtmlComments()
        parser.feed(source)
        parser.close()
        yield from parser.comments
        return
    if language == "dockerfile":
        ensure_dockerfile_language()
    root = SgRoot(source, language).root()
    kinds = COMMENT_KINDS.get(language, ("comment",))
    for match in root.find_all({"rule": {"any": [{"kind": kind} for kind in kinds]}}):
        if workflow and _workflow_version_note(match):
            continue
        yield language, match.range().start.line + 1, match.text().rstrip("\r\n")


def _lexed_comments(language, source):
    lexer = LEXERS[language]()
    opening, closing = ("/*", "*/") if language == "postgresql" else ("<#", "#>")
    line_breaks = [m.start() for m in re.finditer("\n", source)]
    depth = 0
    for offset, kind, token in lexer.get_tokens_unprocessed(source):
        if language in {"postgresql", "powershell"} and kind is Comment.Multiline:
            if token == opening:
                if depth == 0:
                    start = offset
                depth += 1
            elif token == closing and depth:
                depth -= 1
                if depth == 0:
                    yield language, bisect_right(line_breaks, start) + 1, source[start:offset + len(token)]
        elif kind in Comment and kind not in Comment.Preproc:
            yield language, bisect_right(line_breaks, offset) + 1, token.rstrip("\r\n")
    if depth:
        yield language, bisect_right(line_breaks, start) + 1, source[start:].rstrip("\r\n")


def _body(text):
    for opening, closing in (("<!--", "-->"), ("/*", "*/"), ("<#", "#>")):
        if text.startswith(opening):
            return text[len(opening):].removesuffix(closing).strip().lstrip("*").strip()
    return re.sub(r"^(?://|--|#)", "", text, count=1).strip()


def _type_annotation(body):
    if not body.startswith("type:"):
        return False
    annotation = body.removeprefix("type:").strip()
    for mode in ("eval", "func_type"):
        try:
            ast.parse(annotation, mode=mode)
            return True
        except (SyntaxError, ValueError):
            continue
    return False


def _technical(language, text, line):
    if line == 1 and text.startswith("#!"):
        return True
    body = _body(text)
    if LICENSE.match(body.lstrip("!* \t\r\n")):
        return True
    if language in JAVASCRIPT:
        if text.startswith("/**") and DOC_TAG.search(body):
            return True
        return JS_DIRECTIVES.fullmatch(body) is not None
    if language == "python":
        return bool(PY_DIRECTIVES.fullmatch(body) or _type_annotation(body)
                    or (line <= 2 and ENCODING.fullmatch(body)))
    if language == "css":
        return bool(re.fullmatch(STYLELINT, body) or body == "prettier-ignore"
                    or re.fullmatch(r"[#@]\s*sourceMappingURL=\S+", body))
    if language == "bash":
        return bool(re.fullmatch(r"shellcheck\s+(?:(?:disable|enable|shell|source|source-path|external-sources|extended-analysis)=\S+\s*)+", body))
    if language == "go":
        return bool(re.fullmatch(r"(?:go:(?:build|generate|embed|linkname|noinline|noescape|nosplit)\b.*|\+build .+|line \S+:\d+)", body))
    if language in {"swift", "rust", "kotlin"}:
        if re.match(r"/\*\*(?!\*)", text):
            return True
        if language != "kotlin" and re.match(r"///(?!/)", text):
            return True
        if language == "rust" and text.startswith(("//!", "/*!")):
            return True
        return language == "swift" and re.fullmatch(r"swiftlint:(?:enable|disable)(?::(?:next|previous|this))?\s+[\w ]+", body)
    if language == "ruby":
        return line <= 2 and bool(re.fullmatch(r"(?:frozen_string_literal:\s*(?:true|false)|(?:en)?coding:\s*[\w-]+)", body))
    if language == "yaml":
        return bool(re.fullmatch(r"yaml-language-server:\s*\$schema=\S+|yamllint (?:enable|disable(?:-line)?)(?: rule:[\w-]+)*", body))
    if language == "dockerfile":
        return bool(re.fullmatch(r"hadolint (?:global )?ignore=(?:DL|SC)\d{4}(?:,(?:DL|SC)\d{4})*"
                                 r"|hadolint shell=(?:bash|sh|ash|dash|ksh|zsh|powershell|pwsh)", body))
    if language == "toml":
        return bool(re.fullmatch(r":schema\s+\S+", body))
    if language == "jsonc":
        return bool(re.fullmatch(r"biome-ignore\s+(?:lint|assist)/[\w-]+(?:/[\w-]+)*:\s*\S[^\n]*", body))
    if language == "postgresql":
        return bool(re.fullmatch(r"migrate:(?:up|down)(?: transaction:(?:true|false))?|\+goose (?:Up|Down|StatementBegin|StatementEnd|NO TRANSACTION)", body))
    if language == "powershell":
        return bool(re.fullmatch(r"requires\s+-(?:Modules|Version|PSSnapin|PSEdition|RunAsAdministrator)\b.*", body, re.I)
                    or (text.startswith("<#") and re.search(r"(?im)^\s*\.(?:SYNOPSIS|DESCRIPTION|PARAMETER)\b", body)))
    return language == "html" and body in {"prettier-ignore", "prettier-ignore-start", "prettier-ignore-end"}


_HEADER_ENDINGS = {
    "Licensed under the Apache License, Version 2.0": "limitations under the License.",
    "Permission is hereby granted, free of charge": "DEALINGS IN THE SOFTWARE.",
}


def _license_header_lines(source):
    lines = source.split("\n")
    recognized = set()
    for start, line in enumerate(lines[:30]):
        match = re.fullmatch(r"\s*(//|#|--)[ \t]*(.*)", line.rstrip("\r"))
        if not match:
            continue
        ending = next((end for begin, end in _HEADER_ENDINGS.items()
                       if match[2].startswith(begin)), None)
        if ending is None:
            continue
        for index in range(start, min(start + 36, len(lines))):
            continuation = lines[index].strip()
            if not continuation.startswith(match[1]):
                break
            if continuation.endswith(ending):
                recognized.update(range(start + 1, index + 2))
                break
    return recognized


def prohibited_comments(path: str, source: str, *, documentation_input=False):
    language = path_language(path)
    if language == "shebang":
        language = shebang_language(source[:1024].partition("\n")[0])
    if language is None:
        return
    if GENERATED_HEADER.match(source.lstrip("\ufeff")):
        return
    if language in LEXERS:
        comments = _lexed_comments(language, source)
    else:
        workflow = language == "yaml" and PurePosixPath(path).parent == PurePosixPath(".github/workflows")
        comments = _syntax_comments(language, source, workflow=workflow)
    license_lines = _license_header_lines(source)
    directive_count = 0
    if language == "dockerfile":
        for line in source.splitlines():
            if not DOCKER_DIRECTIVE.fullmatch(line):
                break
            directive_count += 1
    for syntax, first, text in comments:
        if first <= directive_count:
            continue
        if syntax == "swift" and first == 1 and PurePosixPath(path).name == "Package.swift":
            if re.fullmatch(r"//\s*swift-tools-version:\s*\d+\.\d+(?:\.\d+)?\s*", text):
                continue
        if syntax in JAVASCRIPT and text.startswith("/*") and _body(text) == "@vite-ignore":
            continue
        if documentation_input and language in JAVASCRIPT and re.match(r"/\*\*(?!\*)", text):
            continue
        if first not in license_lines and not _technical(syntax, text, first):
            yield first, first + text.count("\n")
